import React, {
  useEffect,
  useRef,
  useState,
} from "react";

import * as THREE from "three";

import {
  OrbitControls,
} from "three/examples/jsm/controls/OrbitControls";

import axios from "axios";

import "./EarthScene.css";

/*
=========================================================
API CONFIGURATION
=========================================================
*/

const API_BASE =
  process.env.REACT_APP_API_URL ||
  "http://localhost:5000";

const DEBRIS_API =
  `${API_BASE}/api/debris`;

const DEBRIS_STATUS_API =
  `${API_BASE}/api/debris/status`;

const ISS_API =
  `${API_BASE}/api/iss`;

const COLLISION_API =
  `${API_BASE}/api/collisions`;


/*
=========================================================
UPDATE INTERVALS
=========================================================
*/

const POSITION_UPDATE_INTERVAL = 5000;


/*
=========================================================
EARTH CONSTANTS
=========================================================
*/

const EARTH_RADIUS = 100;

const SIDEREAL_DAY_MS =
  23 * 60 * 60 * 1000 +
  56 * 60 * 1000 +
  4.0905 * 1000;


/*
=========================================================
COMPONENT
=========================================================
*/

const EarthScene = ({
  onBack,
  trackedEvent,
}) => {

  const mountRef =
    useRef(null);

  const viewModeRef =
    useRef("TRACKING");


  /*
  ========================================================
  TIME SCALE
  ========================================================
  */

  const [
    timeScale,
    setTimeScale,
  ] = useState(1);

  const [
  sceneReady,
  setSceneReady,
] = useState(false);

const [
  debrisDataReady,
  setDebrisDataReady,
] = useState(false);

  const timeScaleRef =
    useRef(1);


  /*
  ========================================================
  CAMERA VIEW
  ========================================================
  */

  const [
    viewMode,
    setViewMode,
  ] = useState("TRACKING");


  /*
  ========================================================
  PHASE 3 CAMERA RESTORE
  ========================================================
  */

  const previousCameraStateRef =
    useRef(null);


  /*
  ========================================================
  TELEMETRY STATE
  ========================================================
  */

  const [
    telemetry,
    setTelemetry,
  ] = useState({

    debrisCount: 0,

    connected: false,

    cached: false,

    live: false,

    refreshing: false,

    source:
      "LOCAL CACHE",

    dataset:
      "COSMOS 2251 DEBRIS",

    cacheUpdatedAt:
      null,

    lastPositionUpdate:
      null,

    error:
      null,

    selected:
      null,

    iss:
      null,

    collision:
      null,
  });


  const telemetryRef =
    useRef(telemetry);


  /*
  ========================================================
  TIME SCALE
  ========================================================
  */

  const changeTimeScale =
    (value) => {

      timeScaleRef.current =
        value;

      setTimeScale(
        value
      );
    };


  /*
  ========================================================
  THREE.JS
  ========================================================
  */

  useEffect(() => {

    const mount =
      mountRef.current;

    if (!mount) {
      return;
    }

    let disposed =
      false;


    /*
    ======================================================
    SIZE
    ======================================================
    */

    const width =
      mount.clientWidth ||
      window.innerWidth;

    const height =
      mount.clientHeight ||
      window.innerHeight;


    /*
    ======================================================
    SCENE
    ======================================================
    */

    const scene =
      new THREE.Scene();

    scene.background =
      new THREE.Color(
        0x010409
      );


    /*
    ======================================================
    CAMERA
    ======================================================
    */

    const camera =
      new THREE.PerspectiveCamera(
        45,
        width / height,
        0.1,
        5000
      );

    camera.position.set(
      0,
      160,
      430
    );


    /*
    ======================================================
    RENDERER
    ======================================================
    */

    const renderer =
      new THREE.WebGLRenderer({
        antialias: true,
        powerPreference:
          "high-performance",
      });

    renderer.setPixelRatio(
      Math.min(
        window.devicePixelRatio ||
          1,
        2
      )
    );

    renderer.setSize(
      width,
      height
    );

    renderer.outputColorSpace =
      THREE.SRGBColorSpace;

    mount.appendChild(
      renderer.domElement
    );


    /*
    ======================================================
    ORBIT CONTROLS
    ======================================================
    */

    const controls =
      new OrbitControls(
        camera,
        renderer.domElement
      );

    controls.enableRotate =
      true;

    controls.enablePan =
      true;

    controls.enableZoom =
      true;

    controls.enableDamping =
      true;

    controls.dampingFactor =
      0.06;

    controls.rotateSpeed =
      0.55;

    controls.panSpeed =
      0.5;

    controls.zoomSpeed =
      0.8;

    controls.minDistance =
      115;

    controls.maxDistance =
      1000;

    controls.minPolarAngle =
      0.15;

    controls.maxPolarAngle =
      Math.PI - 0.15;

    controls.target.set(
      0,
      0,
      0
    );

    controls.update();


    /*
    ======================================================
    LIGHTING
    ======================================================
    */

    scene.add(
      new THREE.AmbientLight(
        0xffffff,
        0.38
      )
    );

    const sunLight =
      new THREE.DirectionalLight(
        0xffffff,
        2.1
      );

    sunLight.position.set(
      450,
      250,
      400
    );

    scene.add(
      sunLight
    );

    const rimLight =
      new THREE.DirectionalLight(
        0x4cc9ff,
        0.45
      );

    rimLight.position.set(
      -350,
      50,
      -300
    );

    scene.add(
      rimLight
    );


    /*
    ======================================================
    TEXTURES
    ======================================================
    */

    const loader =
      new THREE.TextureLoader();

    const earthTexture =
      loader.load(
        "/textures/earth_atmos_2048.jpg"
      );

    const cloudTexture =
      loader.load(
        "/textures/earth_clouds_1024.png"
      );


    /*
    ======================================================
    EARTH
    ======================================================
    */

    const earthGroup =
      new THREE.Group();

    scene.add(
      earthGroup
    );

    const earthGeometry =
      new THREE.SphereGeometry(
        EARTH_RADIUS,
        96,
        96
      );

    const earthMaterial =
      new THREE.MeshPhongMaterial({

        map:
          earthTexture,

        shininess:
          12,

        specular:
          new THREE.Color(
            0x1b4055
          ),
      });

    const earth =
      new THREE.Mesh(
        earthGeometry,
        earthMaterial
      );

    earthGroup.add(
      earth
    );


    /*
    ======================================================
    CLOUDS
    ======================================================
    */

    const cloudGeometry =
      new THREE.SphereGeometry(
        EARTH_RADIUS + 2.1,
        72,
        72
      );

    const cloudMaterial =
      new THREE.MeshPhongMaterial({

        map:
          cloudTexture,

        transparent:
          true,

        opacity:
          0.22,

        depthWrite:
          false,
      });

    const clouds =
      new THREE.Mesh(
        cloudGeometry,
        cloudMaterial
      );

    earthGroup.add(
      clouds
    );


    /*
    ======================================================
    ATMOSPHERE
    ======================================================
    */

    const atmosphereGeometry =
      new THREE.SphereGeometry(
        EARTH_RADIUS + 5,
        64,
        64
      );

    const atmosphereMaterial =
      new THREE.MeshBasicMaterial({

        color:
          0x39bdf8,

        transparent:
          true,

        opacity:
          0.055,

        side:
          THREE.BackSide,

        blending:
          THREE.AdditiveBlending,

        depthWrite:
          false,
      });

    const atmosphere =
      new THREE.Mesh(
        atmosphereGeometry,
        atmosphereMaterial
      );

    earthGroup.add(
      atmosphere
    );


    /*
    ======================================================
    STARS
    ======================================================
    */

    const starGeometry =
      new THREE.BufferGeometry();

    const starCount =
      18000;

    const starPositions =
      new Float32Array(
        starCount * 3
      );

    for (
      let i = 0;
      i < starCount;
      i++
    ) {

      const radius =
        1500 +
        Math.random() *
          3000;

      const theta =
        Math.random() *
        Math.PI *
        2;

      const phi =
        Math.acos(
          2 *
            Math.random() -
            1
        );

      starPositions[
        i * 3
      ] =
        radius *
        Math.sin(phi) *
        Math.cos(theta);

      starPositions[
        i * 3 + 1
      ] =
        radius *
        Math.cos(phi);

      starPositions[
        i * 3 + 2
      ] =
        radius *
        Math.sin(phi) *
        Math.sin(theta);
    }

    starGeometry.setAttribute(
      "position",
      new THREE.BufferAttribute(
        starPositions,
        3
      )
    );

    const starMaterial =
      new THREE.PointsMaterial({

        color:
          0xffffff,

        size:
          0.65,

        transparent:
          true,

        opacity:
          0.72,

        sizeAttenuation:
          true,
      });

    const stars =
      new THREE.Points(
        starGeometry,
        starMaterial
      );

    scene.add(
      stars
    );


    /*
    ======================================================
    ORBIT REFERENCE
    ======================================================
    */

    const orbitGroup =
      new THREE.Group();

    scene.add(
      orbitGroup
    );


    /*
    ======================================================
    COLLISION VISUALIZATION
    ======================================================
    */

    const collisionGroup =
      new THREE.Group();

    scene.add(
      collisionGroup
    );

    const collisionLineMaterial =
      new THREE.LineBasicMaterial({
        color: 0xff3b30,
        transparent: true,
        opacity: 0.9,
      });

    const collisionMarkerMaterial =
      new THREE.MeshBasicMaterial({
        color: 0xff3b30,
      });

    const collisionMarkerGeometry =
      new THREE.SphereGeometry(
        2.8,
        16,
        16
      );

    let collisionLine =
      null;

    let collisionMarker1 =
      null;

    let collisionMarker2 =
      null;


    const clearCollisionVisualization =
      () => {

        if (collisionLine) {

          collisionGroup.remove(
            collisionLine
          );

          collisionLine.geometry.dispose();

          collisionLine =
            null;
        }

        if (collisionMarker1) {

          collisionGroup.remove(
            collisionMarker1
          );

          collisionMarker1 =
            null;
        }

        if (collisionMarker2) {

          collisionGroup.remove(
            collisionMarker2
          );

          collisionMarker2 =
            null;
        }
      };


    const showCollisionVisualization =
      (
        event,
        currentDebrisData
      ) => {

        clearCollisionVisualization();

        if (
          !event ||
          !Array.isArray(currentDebrisData)
        ) {
          return;
        }

        const norad1 =
          String(
            event.object1?.noradId || ""
          );

        const norad2 =
          String(
            event.object2?.noradId || ""
          );

        const object1 =
          currentDebrisData.find(
            object =>
              String(
                object.noradId
              ) === norad1
          );

        const object2 =
          currentDebrisData.find(
            object =>
              String(
                object.noradId
              ) === norad2
          );

        if (
          !object1 ||
          !object2
        ) {

          console.warn(
            "Collision objects not found in debris cache",
            norad1,
            norad2
          );

          return;
        }

        const position1 =
          convertCoordsToVector(
            object1.lat,
            object1.lon,
            object1.alt
          );

        const position2 =
          convertCoordsToVector(
            object2.lat,
            object2.lon,
            object2.alt
          );

        const geometry =
          new THREE.BufferGeometry()
            .setFromPoints([
              position1,
              position2,
            ]);

        collisionLine =
          new THREE.Line(
            geometry,
            collisionLineMaterial
          );

        collisionGroup.add(
          collisionLine
        );

        collisionMarker1 =
          new THREE.Mesh(
            collisionMarkerGeometry,
            collisionMarkerMaterial
          );

        collisionMarker2 =
          new THREE.Mesh(
            collisionMarkerGeometry,
            collisionMarkerMaterial
          );

        collisionMarker1.position.copy(
          position1
        );

        collisionMarker2.position.copy(
          position2
        );

        collisionGroup.add(
          collisionMarker1
        );

        collisionGroup.add(
          collisionMarker2
        );
      };


    /*
    ======================================================
    CREATE ORBIT RING
    ======================================================
    */

    const createOrbitRing =
      (
        radius,
        rotationX,
        rotationZ,
        opacity
      ) => {

        const points =
          [];

        for (
          let i = 0;
          i <= 128;
          i++
        ) {

          const angle =
            (i / 128) *
            Math.PI *
            2;

          points.push(
            new THREE.Vector3(
              radius *
                Math.cos(angle),

              0,

              radius *
                Math.sin(angle)
            )
          );
        }

        const geometry =
          new THREE.BufferGeometry()
            .setFromPoints(
              points
            );

        const material =
          new THREE.LineBasicMaterial({

            color:
              0x3da8d8,

            transparent:
              true,

            opacity,
          });

        const ring =
          new THREE.LineLoop(
            geometry,
            material
          );

        ring.rotation.x =
          rotationX;

        ring.rotation.z =
          rotationZ;

        orbitGroup.add(
          ring
        );

        return ring;
      };


    createOrbitRing(
      122,
      THREE.MathUtils.degToRad(12),
      THREE.MathUtils.degToRad(20),
      0.13
    );

    createOrbitRing(
      145,
      THREE.MathUtils.degToRad(42),
      THREE.MathUtils.degToRad(-30),
      0.1
    );

    createOrbitRing(
      175,
      THREE.MathUtils.degToRad(72),
      THREE.MathUtils.degToRad(50),
      0.075
    );

    createOrbitRing(
      215,
      THREE.MathUtils.degToRad(25),
      THREE.MathUtils.degToRad(80),
      0.06
    );


    /*
    ======================================================
    COORDINATE CONVERSION
    ======================================================
    */

    const convertCoordsToVector =
      (
        lat,
        lon,
        alt
      ) => {

        const safeLat =
          Number(lat) || 0;

        const safeLon =
          Number(lon) || 0;

        const safeAlt =
          Number(alt) || 0;

        const visualAltitude =
          Math.max(
            10,
            Math.min(
              260,
              safeAlt / 1000
            )
          );

        const radius =
          EARTH_RADIUS +
          visualAltitude;

        const phi =
          (90 - safeLat) *
          Math.PI /
          180;

        const theta =
          (safeLon + 180) *
          Math.PI /
          180;

        return new THREE.Vector3(

          -radius *
            Math.sin(phi) *
            Math.cos(theta),

          radius *
            Math.cos(phi),

          radius *
            Math.sin(phi) *
            Math.sin(theta)
        );
      };


    /*
    ======================================================
    DEBRIS
    ======================================================
    */

    const debrisGroup =
      new THREE.Group();

    scene.add(
      debrisGroup
    );

    const debrisGeometry =
      new THREE.SphereGeometry(
        1.55,
        8,
        8
      );

    const debrisMaterial =
      new THREE.MeshStandardMaterial({

        color:
          0x55d9ff,

        emissive:
          0x073a4f,

        emissiveIntensity:
          1.7,

        roughness:
          0.4,

        metalness:
          0.3,
      });

    let debrisMesh =
      null;

    let debrisData =
      [];

    const debrisMatrix =
      new THREE.Matrix4();


    /*
    ======================================================
    CREATE / REUSE DEBRIS MESH
    ======================================================
    */

    const ensureDebrisMesh =
      (count) => {

        if (
          count <= 0
        ) {

          if (
            debrisMesh
          ) {

            debrisGroup.remove(
              debrisMesh
            );

            debrisMesh =
              null;
          }

          return;
        }

        if (
          debrisMesh &&
          debrisMesh.count ===
            count
        ) {

          return;
        }

        if (
          debrisMesh
        ) {

          debrisGroup.remove(
            debrisMesh
          );
        }

        debrisMesh =
          new THREE.InstancedMesh(
            debrisGeometry,
            debrisMaterial,
            count
          );

        debrisMesh.frustumCulled =
          false;

        debrisMesh.instanceMatrix.setUsage(
          THREE.DynamicDrawUsage
        );

        debrisGroup.add(
          debrisMesh
        );
      };


    /*
    ======================================================
    SELECTED OBJECT
    ======================================================
    */

    const selectedMarker =
      new THREE.Group();

    const selectedRingGeometry =
      new THREE.RingGeometry(
        4,
        4.7,
        32
      );

    const selectedRingMaterial =
      new THREE.MeshBasicMaterial({

        color:
          0xffffff,

        transparent:
          true,

        opacity:
          0.9,

        side:
          THREE.DoubleSide,
      });

    const selectedRing =
      new THREE.Mesh(
        selectedRingGeometry,
        selectedRingMaterial
      );

    selectedMarker.add(
      selectedRing
    );


    const selectedCoreGeometry =
      new THREE.SphereGeometry(
        2.4,
        12,
        12
      );

    const selectedCoreMaterial =
      new THREE.MeshBasicMaterial({

        color:
          0xffffff,
      });

    const selectedCore =
      new THREE.Mesh(
        selectedCoreGeometry,
        selectedCoreMaterial
      );

    selectedMarker.add(
      selectedCore
    );

    selectedMarker.visible =
      false;

    scene.add(
      selectedMarker
    );


    /*
    ======================================================
    SELECTED ORBIT
    ======================================================
    */

    let selectedOrbit =
