) {
  let pulseSpeed = 0.005;
  let pulseAmount = 0.10;

  if (
    trackedCollisionRisk ===
    "CRITICAL"
  ) {
    pulseSpeed = 0.012;
    pulseAmount = 0.28;
  } else if (
    trackedCollisionRisk ===
    "HIGH"
  ) {
    pulseSpeed = 0.009;
    pulseAmount = 0.22;
  } else if (
    trackedCollisionRisk ===
    "MEDIUM"
  ) {
    pulseSpeed = 0.007;
    pulseAmount = 0.16;
  }

  const pulse =
    1 +
    Math.sin(
      performance.now() *
        pulseSpeed
    ) *
      pulseAmount;

  trackedCollisionPulseObjects.forEach(
    (object) => {
      object.scale.setScalar(
        pulse
      );
    }
  );
}
        /*
         * ISS glow
         */

        issGlow.scale.setScalar(
          1 +
            Math.sin(
              performance.now() *
                0.004
            ) *
              0.12
        );


        controls.update();

        renderer.render(
          scene,
          camera
        );
      };


    animate();


    /*
    ======================================================
    WINDOW RESIZE
    ======================================================
    */

    const handleResize =
      () => {

        const newWidth =
          mount.clientWidth ||
          window.innerWidth;

        const newHeight =
          mount.clientHeight ||
          window.innerHeight;

        camera.aspect =
          newWidth /
          newHeight;

        camera.updateProjectionMatrix();

        renderer.setSize(
          newWidth,
          newHeight
        );
      };


    window.addEventListener(
      "resize",
      handleResize
    );


    /*
    ======================================================
    CLEANUP
    ======================================================
    */

    return () => {

      disposed =
        true;

      cancelAnimationFrame(
        animationFrame
      );

      clearInterval(
        positionInterval
      );

      clearInterval(
        statusInterval
      );

      clearInterval(
        issInterval
      );

      clearInterval(
        collisionInterval
      );

      window.removeEventListener(
        "resize",
        handleResize
      );

      renderer.domElement.removeEventListener(
        "click",
        handlePointerClick
      );

      controls.dispose();

      clearCollisionVisualization();

      clearSelectedOrbit();

      clearTrackedCollision();


      /*
       * Dispose Three.js resources.
       */

      earthGeometry.dispose();
      earthMaterial.dispose();

      cloudGeometry.dispose();
      cloudMaterial.dispose();

      atmosphereGeometry.dispose();
      atmosphereMaterial.dispose();

      starGeometry.dispose();
      starMaterial.dispose();

      debrisGeometry.dispose();
      debrisMaterial.dispose();

      selectedRingGeometry.dispose();
      selectedRingMaterial.dispose();

      selectedCoreGeometry.dispose();
      selectedCoreMaterial.dispose();

      issGeometry.dispose();
      issMaterial.dispose();

      issGlowGeometry.dispose();
      issGlowMaterial.dispose();

      renderer.dispose();


      mount.__setCameraView =
        null;

      mount.__resetCamera =
        null;

      mount.__clearSelection =
        null;

      mount.__trackCollision =
        null;

      mount.__restorePreviousCamera =
        null;


      if (
        renderer
          .domElement
          .parentNode ===
        mount
      ) {

        mount.removeChild(
          renderer.domElement
        );
      }

    };

  }, []);


  /*
  ==========================================================
  TRACK COLLISION EVENT
  ==========================================================
  */

useEffect(() => {

  if (!trackedEvent) {
    return;
  }

  if (!sceneReady) {
    return;
  }

  if (!debrisDataReady) {
    return;
  }

  const track =
    mountRef.current?.__trackCollision;

  if (!track) {
    console.warn(
      "AI tracking requested, but EarthScene tracking API is not ready."
    );
    return;
  }

  console.log(
    "AI TRACKING EFFECT FIRED",
    {
      object1:
        trackedEvent?.object1?.noradId,
      object2:
        trackedEvent?.object2?.noradId,
      risk:
        trackedEvent?.aiPrediction?.risk_level ||
        trackedEvent?.closestApproach?.riskLevel ||
        "UNKNOWN",
    }
  );

  track(
    trackedEvent
  );

}, [
  trackedEvent,
  sceneReady,
  debrisDataReady,
]);

  /*
  ==========================================================
  RESTORE CAMERA WHEN TRACK EVENT ENDS
  ==========================================================
  */

  useEffect(() => {

    if (trackedEvent) {
      return;
    }

    const restore =
      mountRef.current?.__restorePreviousCamera;

    if (!restore) {
      return;
    }

    restore();

  }, [trackedEvent]);


  /*
  ==========================================================
  TIME SCALE LABEL
  ==========================================================
  */

  const getTimeScaleLabel =
    () => {

      if (
        timeScale === 1
      ) {
        return "REAL-TIME";
      }

      if (
        timeScale === 60
      ) {
        return "1 MINUTE / SECOND";
      }

      if (
        timeScale === 600
      ) {
        return "10 MINUTES / SECOND";
      }

      if (
        timeScale === 3600
      ) {
        return "1 HOUR / SECOND";
      }

      return `${timeScale}×`;
    };


  /*
  ==========================================================
  CACHE TIME
  ==========================================================
  */

  const formatCacheTime =
    () => {

      if (
        !telemetry.cacheUpdatedAt
      ) {
        return "--:--:--";
      }

      const date =
        new Date(
          telemetry.cacheUpdatedAt
        );

      if (
        Number.isNaN(
          date.getTime()
        )
      ) {
        return "--:--:--";
      }

      return date.toLocaleTimeString(
        [],
        {
          hour12:
            false,
        }
      );
    };


  /*
  ==========================================================
  POSITION TIME
  ==========================================================
  */

  const formatPositionTime =
    () => {

      if (
        !telemetry.lastPositionUpdate
      ) {
        return "--:--:--";
      }

      return telemetry.lastPositionUpdate.toLocaleTimeString(
        [],
        {
          hour12:
            false,
        }
      );
    };


  /*
  ==========================================================
  RENDER
  ==========================================================
  */

  return (

    <div className="earth-tracker">


      {/* =================================================
          THREE.JS CANVAS
      ================================================= */}

      <div
        ref={mountRef}
        className="earth-canvas"
      />


      {/* =================================================
          TOP BAR
      ================================================= */}

      <header className="tracker-topbar">

        <div className="tracker-brand">

          <button
            className="tracker-back"
            onClick={() => {

              if (
                onBack
              ) {

                onBack();

              }

            }}
          >
            ←
          </button>


          <div>

            <strong>
              ORBITAL
            </strong>

            <span>
              DEBRIS TRACKER
            </span>

          </div>

        </div>


        <div className="tracker-title">

          <span>
            EARTH ORBITAL MONITORING
          </span>

          <strong>
            LIVE TRACKING ENVIRONMENT
          </strong>

        </div>


        <div className="tracker-connection">

          <span
            className={
              telemetry.connected
                ? "connection-dot online"
                : "connection-dot"
            }
          />


          <div>

            <strong>

              {telemetry.connected
                ? "ORBITAL FEED ONLINE"
                : "ORBITAL FEED OFFLINE"}

            </strong>


            <small>

              POSITION{" "}
              {formatPositionTime()}

            </small>

          </div>

        </div>

      </header>


      {/* =================================================
          LEFT TELEMETRY
      ================================================= */}

      <aside className="tracker-left-panel">

        <div className="hud-panel">

          <div className="hud-panel-title">

            <span>
              LIVE TELEMETRY
            </span>

            <small>
              01
            </small>

          </div>


          <div className="hud-stat">

            <span>
              TRACKED OBJECTS
            </span>

            <strong>
              {telemetry.debrisCount.toLocaleString()}
            </strong>

          </div>


          <div className="hud-stat">

            <span>
              DATA MODE
            </span>

            <strong className="green">

              {telemetry.cached
                ? "CACHE + LIVE"
                : "WAITING"}

            </strong>

          </div>


          <div className="hud-stat">

            <span>
              ORBITAL SOURCE
            </span>

            <strong>
              LOCAL CACHE
            </strong>

          </div>


          <div className="hud-stat">

            <span>
              CACHE UPDATED
            </span>

            <strong>
              {formatCacheTime()}
            </strong>

          </div>


          <div className="hud-stat">

            <span>
              PROPAGATION
            </span>

            <strong className="green">
              SGP4
            </strong>

          </div>


          <div className="hud-stat">

            <span>
              EXTERNAL REFRESH
            </span>

            <strong>
              2 HOURS
            </strong>

          </div>

        </div>


        {/* =================================================
            LEGEND
        ================================================= */}

        <div className="hud-panel legend-panel">

          <div className="hud-panel-title">

            <span>
              OBJECT LEGEND
            </span>

            <small>
              02
            </small>

          </div>


          <div className="legend-row">

            <span className="legend-dot debris-dot" />

            <span>
              SPACE DEBRIS
            </span>

          </div>


          <div className="legend-row">

            <span className="legend-dot iss-dot" />

            <span>
              INTERNATIONAL SPACE STATION
            </span>

          </div>


          <div className="legend-row">

            <span className="legend-line" />

            <span>
              REFERENCE ORBIT
            </span>

          </div>

        </div>

      </aside>


      {/* =================================================
          MISSION CONTROL
      ================================================= */}

      <aside className="tracker-right-panel">

        <div className="hud-panel mission-control-panel">


          {/* HEADER */}

          <div className="hud-panel-title">

            <span>
              MISSION CONTROL
            </span>

            <small>
              03
            </small>

          </div>


          {/* =================================================
              TIME SCALE
          ================================================= */}

          <section className="mission-section">

            <div className="mission-section-label">
              TIME SCALE
            </div>


            <div className="time-scale-grid">

              <button
                type="button"
                className={
                  timeScale === 1
                    ? "view-button active"
                    : "view-button"
                }
                onClick={() =>
                  changeTimeScale(
                    1
                  )
                }
              >

                <span>
                  1×
                </span>

                <small>
                  REAL TIME
                </small>

              </button>


              <button
                type="button"
                className={
                  timeScale === 60
                    ? "view-button active"
                    : "view-button"
                }
                onClick={() =>
                  changeTimeScale(
                    60
                  )
                }
              >

                <span>
                  60×
                </span>

                <small>
                  1 MIN / SEC
                </small>

              </button>


              <button
                type="button"
                className={
                  timeScale === 600
                    ? "view-button active"
                    : "view-button"
                }
                onClick={() =>
                  changeTimeScale(
                    600
                  )
                }
              >

                <span>
                  600×
                </span>

                <small>
                  10 MIN / SEC
                </small>

              </button>


              <button
                type="button"
                className={
                  timeScale === 3600
                    ? "view-button active"
                    : "view-button"
                }
                onClick={() =>
                  changeTimeScale(
                    3600
                  )
                }
              >

                <span>
                  3600×
                </span>

                <small>
                  1 HOUR / SEC
                </small>

              </button>

            </div>


            <div className="time-scale-current">

              {getTimeScaleLabel()}

            </div>

          </section>


          {/* =================================================
              CAMERA CONTROL
          ================================================= */}

          <section className="mission-section">

            <div className="mission-section-label">
              CAMERA CONTROL
            </div>


            <div className="camera-grid">

              <button
                type="button"
                className={
                  viewMode === "EARTH"
                    ? "camera-button active"
                    : "camera-button"
                }
                onClick={() =>
                  mountRef.current?.__setCameraView?.(
                    "EARTH"
                  )
                }
              >

                <strong>
                  EARTH
                </strong>

                <small>
                  PLANET VIEW
                </small>

              </button>


              <button
                type="button"
                className={
                  viewMode === "TRACKING"
                    ? "camera-button active"
                    : "camera-button"
                }
                onClick={() =>
                  mountRef.current?.__setCameraView?.(
                    "TRACKING"
                  )
                }
              >

                <strong>
                  TRACKING
                </strong>

                <small>
                  ORBITAL VIEW
                </small>

              </button>


              <button
                type="button"
                className={
                  viewMode === "WIDE"
                    ? "camera-button active"
                    : "camera-button"
                }
                onClick={() =>
                  mountRef.current?.__setCameraView?.(
                    "WIDE"
                  )
                }
              >

                <strong>
                  WIDE ORBIT
                </strong>

                <small>
                  FULL SYSTEM
                </small>

              </button>


              <button
                type="button"
                className="camera-button reset"
                onClick={() =>
                  mountRef.current?.__resetCamera?.()
                }
              >

                <strong>
                  RESET
                </strong>

                <small>
                  DEFAULT CAMERA
                </small>

              </button>

            </div>

          </section>


          {/* =================================================
              MANUAL CAMERA
          ================================================= */}

          <section className="mission-section">

            <div className="mission-section-label">
              MANUAL CAMERA
            </div>


            <div className="camera-help">

              <div>

                <span>
                  ROTATE
                </span>

                <strong>
                  LEFT DRAG
                </strong>

              </div>


              <div>

                <span>
                  PAN
                </span>

                <strong>
                  RIGHT DRAG
                </strong>

              </div>


              <div>

                <span>
                  ZOOM
                </span>

                <strong>
                  SCROLL
                </strong>

              </div>


              <div>

                <span>
                  SELECT
                </span>

                <strong>
                  CLICK OBJECT
                </strong>

              </div>

            </div>

          </section>


          {/* =================================================
              SYSTEM STATUS
          ================================================= */}

          <section className="mission-section">

            <div className="mission-section-label">
              SYSTEM STATUS
            </div>


            <div className="mission-status-row">

              <span>
                ORBITAL FEED
              </span>

              <strong
                className={
                  telemetry.connected
                    ? "green"
                    : "red"
                }
              >

                {telemetry.connected
                  ? "ONLINE"
                  : "OFFLINE"}

              </strong>

            </div>


            <div className="mission-status-row">

              <span>
                CACHE
              </span>

              <strong
                className={
                  telemetry.cached
                    ? "green"
                    : "red"
                }
              >

                {telemetry.cached
                  ? "READY"
                  : "EMPTY"}

              </strong>

            </div>


            <div className="mission-status-row">

              <span>
                UPSTREAM REFRESH
              </span>

              <strong>

                {telemetry.refreshing
                  ? "REFRESHING"
                  : "2 HOURS"}

              </strong>

            </div>


            <div className="mission-status-row">

              <span>
                PROPAGATION
              </span>

              <strong className="green">
                SGP4
              </strong>

            </div>


            <div className="mission-status-row">

              <span>
                OBJECTS
              </span>

              <strong>
                {telemetry.debrisCount.toLocaleString()}
              </strong>

            </div>

          </section>

        </div>

      </aside>


      {/* =================================================
          SELECTED OBJECT
      ================================================= */}

      {telemetry.selected && (

        <div className="selected-object-panel">

          <div className="selected-header">

            <div>

              <span>
                SELECTED OBJECT
              </span>

              <strong>
                {
                  telemetry.selected.name ||
                  `OBJECT-${telemetry.selected.index + 1}`
                }
              </strong>

            </div>


            <button
              onClick={() =>
                mountRef.current?.__clearSelection?.()
              }
            >
              ×
            </button>

          </div>


          <div className="selected-grid">

            <div>

              <span>
                LATITUDE
              </span>

              <strong>
                {Number(
                  telemetry.selected.lat
                ).toFixed(2)}
                °
              </strong>

            </div>


            <div>

              <span>
                LONGITUDE
              </span>

              <strong>
                {Number(
                  telemetry.selected.lon
                ).toFixed(2)}
                °
              </strong>

            </div>


            <div>

              <span>
                ALTITUDE
              </span>

              <strong>
                {Number(
                  telemetry.selected.alt
                ).toFixed(2)}
                km
              </strong>

            </div>


            <div>

              <span>
                VELOCITY
              </span>

              <strong>

                {telemetry.selected.velocity
                  ? `${Number(
                      telemetry.selected.velocity
                    ).toFixed(2)} km/s`
                  : "—"}

              </strong>

            </div>

          </div>


          <div className="selected-note">

            Position calculated from the
            local orbital cache using
            satellite.js / SGP4.

          </div>

        </div>

      )}


      {/* =================================================
          ISS POSITION
      ================================================= */}

      {telemetry.iss && (

        <div className="iss-panel">

          <div className="iss-panel-title">

            <span className="iss-live-dot" />

            ISS LIVE POSITION

          </div>


          <div className="iss-data">

            <span>
              LAT{" "}
              {Number(
                telemetry.iss.lat
              ).toFixed(2)}
              °
            </span>

            <span>
              LON{" "}
              {Number(
                telemetry.iss.lon
              ).toFixed(2)}
              °
            </span>

            <span>
              ALT{" "}
              {Number(
                telemetry.iss.alt
              ).toFixed(2)}
              km
            </span>

          </div>

        </div>

      )}


      {/* =================================================
          BOTTOM STATUS
      ================================================= */}

      <div className="tracker-bottom">

        <div>

          <span>
            TIME SCALE
          </span>

          <strong>
            {timeScale}×
          </strong>

        </div>


        <div>

          <span>
            VIEW
          </span>

          <strong>
            {viewMode}
          </strong>

        </div>


        <div>

          <span>
            DATA SOURCE
          </span>

          <strong>
            LOCAL CACHE
          </strong>

        </div>


        <div>

          <span>
            CACHE
          </span>

          <strong>
            {formatCacheTime()}
          </strong>

        </div>


        <div>

          <span>
            OBJECTS
          </span>

          <strong>
            {telemetry.debrisCount.toLocaleString()}
          </strong>

        </div>


        <div>

          <span>
            STATUS
          </span>

          <strong
            className={
              telemetry.connected
                ? "green"
                : "red"
            }
          >

            {telemetry.connected
              ? "OPERATIONAL"
              : "OFFLINE"}

          </strong>

        </div>

      </div>


      {/* =================================================
          ERROR
      ================================================= */}

      {telemetry.error && (

        <div className="tracker-error">

          <span>
            !
          </span>

          {telemetry.error}

        </div>

      )}

    </div>
  );
};


export default EarthScene;
